using System;
using System.Collections.Generic;
using UnityEngine;

// Icon label style for the touch buttons. Artwork by BIRDY141, contributed in
// https://github.com/martin2844/OpenBonk/issues/29 (trimmed and resized to
// 128x128). Keys are touch button actions.
public static class OpenBonkTouchIcons
{
    private static readonly Dictionary<string, string> Png = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
    {
        ["Jump"] = "",
        ["Slide"] = "",
        ["Interact"] = "",
        ["Aim"] = "",
    };

    private static readonly Dictionary<string, Sprite> Loaded = new Dictionary<string, Sprite>(StringComparer.OrdinalIgnoreCase);

    public static Sprite Get(string action)
    {
        if (string.Equals(action, "Jump Bhop", StringComparison.OrdinalIgnoreCase)) action = "Jump";
        if (string.IsNullOrEmpty(action) || !Png.TryGetValue(action, out var data)) return null;
        if (Loaded.TryGetValue(action, out var cached)) return cached;
        Sprite sprite = null;
        try
        {
            var texture = new Texture2D(2, 2, TextureFormat.RGBA32, true);
            if (texture.LoadImage(Convert.FromBase64String(data)))
            {
                texture.wrapMode = TextureWrapMode.Clamp; texture.filterMode = FilterMode.Trilinear;
                sprite = Sprite.Create(texture, new Rect(0, 0, texture.width, texture.height), new Vector2(.5f, .5f), 100f);
            }
            else UnityEngine.Object.Destroy(texture);
        }
        catch (Exception e) { Debug.LogWarning("OpenBonk touch icon " + action + ": " + e.GetType().Name); }
        Loaded[action] = sprite;
        return sprite;
    }
}
